c***************************# FJ@HU Berlin #***********************************
  
c  "Delta alpha"               Update version (18/08/2026) 
  
c ISCAN: -1, Ismooth: 0, IGS: 0, DSET: EPM2, iplot: 0 itestflavorspl: 0
c IKE,Emin,Emax,NP,N,EPSREL:  1, 6.0000E-01, 1.4000E+00, 100, 10, 1.00E-02, 
